static NSURL *Copy(NSDictionary *entry,NSError **error){__block BOOL done=NO;__block NSURL *result;__block NSError *failure;TFAIStageSandboxAttachment(entry,nil,^(NSURL *url,NSError *e){result=url;failure=e;done=YES;});NSDate *end=[NSDate dateWithTimeIntervalSinceNow:10];while(!done&&end.timeIntervalSinceNow>0)[NSRunLoop.currentRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.02]];if(error)*error=failure;return result;}
int main(int argc,char **argv){@autoreleasepool{NSString *root=@(argv[1]);[NSFileManager.defaultManager createDirectoryAtPath:root withIntermediateDirectories:YES attributes:nil error:nil];NSString *path=[root stringByAppendingPathComponent:@"Fixture.ipa"];NSData *payload=[@"PK IPA ORIGINAL" dataUsingEncoding:NSUTF8StringEncoding];[payload writeToFile:path atomically:YES];NSError *error=nil;NSDictionary *entry=TFAIClassDumpStage([NSURL fileURLWithPath:path],&error);Check(entry[@"classDumpInputID"]!=nil,@"actual classdump staging retains IPA");NSURL *copy=Copy(entry,&error);Check(copy!=nil,[NSString stringWithFormat:@"original IPA bridges without localSnapshot %@",error]);Check([copy.lastPathComponent isEqual:@"Fixture.ipa"],@"original filename preserved");Check([[NSData dataWithContentsOfURL:copy] isEqual:payload],@"bridged bytes exact");[NSFileManager.defaultManager removeItemAtURL:copy.URLByDeletingLastPathComponent error:nil];NSString *input=[NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject stringByAppendingPathComponent:[NSString stringWithFormat:@"AIClassDumpInputs/%@/input.ipa",entry[@"classDumpInputID"]]];Check([NSFileManager.defaultManager fileExistsAtPath:input],@"source IPA not removed by staging cleanup");[@"TAMPER" writeToFile:input atomically:YES encoding:NSUTF8StringEncoding error:nil];Check(!Copy(entry,&error)&&[error.localizedDescription containsString:@"无需更换会话"],@"changed original rejected with actionable same-session error");NSMutableDictionary *invalid=[entry mutableCopy];invalid[@"classDumpInputID"]=@"../../escape";Check(!Copy(invalid,&error),@"invalid input ID refused");NSLog(@"TOTAL %d IPA bridge checks passed",checks);}return 0;}
